res_vis = primitives.call(name="observe_robotwin2_visual", camera_name="head_camera")
print("vis ok:", res_vis.ok)
if res_vis.ok:
    out = res_vis.output
    print("vis keys:", list(out.keys()))
    print("handles:", out.get("evidence_handles"))
    print("seg summary:", out.get("segmentation_summary") or out.get("actor_segmentation_summary"))

for actor in ["bowl1", "bowl2", "table"]:
    r_loc = primitives.call(name="locate_robotwin2_actor", actor_name=actor)
    if r_loc.ok:
        print(f"locate {actor}:", r_loc.output)
    for pt in ["contact", "functional", "target", "orientation"]:
        r_pt = primitives.call(name="inspect_robotwin2_actor_points", actor_name=actor, point_type=pt)
        if r_pt.ok:
            print(f"points {actor} {pt}:", r_pt.output)

if res_vis.ok:
    for k, v in res_vis.output.items():
        if k not in ["rgb", "depth", "actor_segmentation", "mesh_segmentation", "pointcloud"]:
            print("vis", k, ":", v)

for actor in ["bowl1", "bowl2"]:
    m = primitives.call(name="measure_robotwin2_actor_visual", actor_label=actor, camera_name="head_camera")
    print(f"measure {actor} ok:", m.ok)
    if m.ok:
        print(f"measure {actor}:", m.output)

for pt in ["contact", "functional", "target"]:
    r1 = primitives.call(name="inspect_robotwin2_actor_points", actor_name="bowl1", point_type=pt)
    if r1.ok:
        print(f"bowl1 {pt}:", [p["pose"] for p in r1.output.get("points", [])])
    r2 = primitives.call(name="inspect_robotwin2_actor_points", actor_name="bowl2", point_type=pt)
    if r2.ok:
        print(f"bowl2 {pt}:", [p["pose"] for p in r2.output.get("points", [])])

m1 = primitives.call(name="measure_robotwin2_actor_visual", actor_label="bowl1", camera_name="head_camera", max_points=5)
m2 = primitives.call(name="measure_robotwin2_actor_visual", actor_label="bowl2", camera_name="head_camera", max_points=5)
mt = primitives.call(name="measure_robotwin2_actor_visual", actor_label="table", camera_name="head_camera", max_points=5)

for name, m in [("bowl1", m1), ("bowl2", m2), ("table", mt)]:
    print(name, "ok:", m.ok)
    if m.ok:
        d = {k: v for k, v in m.output.items() if k != "points_world"}
        print(name, d)

for pt in ["contact", "functional", "target"]:
    rt = primitives.call(name="inspect_robotwin2_actor_points", actor_name="table", point_type=pt)
    if rt.ok:
        print("table", pt, ":", rt.output.get("points"))

